"use server";

import { eq, sql } from "drizzle-orm";
import { serverAction } from "rwsdk/worker";

import { db } from "@/db";

const SINGLETON_ID = 1;

/**
 * Increment the persisted like count by exactly one.
 *
 * Uses a RedwoodSDK `serverAction` so that when invoked from a client
 * component the page re-renders with the new value automatically.
 */
export const incrementLike = serverAction(async function incrementLike() {
  // Ensure the singleton row exists. Using `INSERT OR IGNORE` keeps the
  // very first like on a fresh database from failing.
  await db
    .insert(db.$with?.("placeholder") ?? (db as any))
    .into?.(undefined as any)
    .catch(() => undefined);

  await db.run(sql`
    INSERT OR IGNORE INTO likes (id, count, updated_at)
    VALUES (${SINGLETON_ID}, 0, '')
  `);

  const updated = await db
    .update((await import("@/db/schema")).likes)
    .set({
      count: sql`${(await import("@/db/schema")).likes.count} + 1`,
      updatedAt: new Date().toISOString(),
    })
    .where(eq((await import("@/db/schema")).likes.id, SINGLETON_ID))
    .returning({ count: (await import("@/db/schema")).likes.count });

  return updated[0]?.count ?? 1;
});

"use server";

import { sql } from "drizzle-orm";
import { serverAction } from "rwsdk/worker";

import { db } from "@/db";
import { likes } from "@/db/schema";

const SINGLETON_ID = 1;

/**
 * Increment the persisted like count by exactly one.
 *
 * Wrapped with RedwoodSDK's `serverAction` so that, when invoked from a
 * client component, the React page re-renders with the new value after
 * the action resolves.
 */
export const incrementLike = serverAction(async function incrementLike() {
  // Make sure the singleton row exists. On a brand new database the row is
  // missing; the very first click needs to create it.
  await db.run(sql`
    INSERT OR IGNORE INTO likes (id, count, updated_at)
    VALUES (${SINGLETON_ID}, 0, '')
  `);

  // Atomically bump the counter by one.
  const updated = await db
    .update(likes)
    .set({
      count: sql`${likes.count} + 1`,
      updatedAt: new Date().toISOString(),
    })
    .where(sql`${likes.id} = ${SINGLETON_ID}`)
    .returning({ count: likes.count });

  return updated[0]?.count ?? 1;
});

"use client";

import { useTransition } from "react";

import { incrementLike } from "./actions";

/**
 * Client component that renders the "Like" button. Clicking it invokes
 * the `incrementLike` serverAction, which mutates D1 and triggers a
 * re-render of the route so the visible count is refreshed.
 */
export function LikeButton() {
  const [pending, startTransition] = useTransition();

  const handleClick = () => {
    startTransition(() => {
      void incrementLike();
    });
  };

  return (
    <button
      type="button"
      data-testid="like-button"
      onClick={handleClick}
      disabled={pending}
      aria-busy={pending}
    >
      {pending ? "Liking…" : "Like"}
    </button>
  );
}

import { eq } from "drizzle-orm";

import { LikeButton } from "@/app/likes/LikeButton";
import { db } from "@/db";
import { likes } from "@/db/schema";

const SINGLETON_ID = 1;

/**
 * Read the persisted like count from D1.
 *
 * The `likes` table holds at most one row (id = 1). When the row is
 * missing, we treat the count as 0 so a fresh database starts at zero.
 */
async function getLikeCount(): Promise<number> {
  const row = await db
    .select({ count: likes.count })
    .from(likes)
    .where(eq(likes.id, SINGLETON_ID))
    .limit(1);

  return row[0]?.count ?? 0;
}

export const Home = async () => {
  const count = await getLikeCount();

  return (
    <main
      style={{
        fontFamily: "system-ui, sans-serif",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        gap: "1rem",
      }}
    >
      <h1>Like Button Demo</h1>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "0.75rem",
        }}
      >
        <LikeButton />
        <span data-testid="like-count">{count}</span>
      </div>
    </main>
  );
};

